SELECT C.PRODG PRODG1,C.MODULE,E.DEPT_ID FROM ( SELECT A.PRODG,A.MODULE,A.EQP_CNT/A.EQPG_CNT RATIO,B.DEPT_ID1 ,CASE WHEN SUBSTR(B.DEPT_ID1,1,2) IN ('RI','RH') THEN 'TD' WHEN SUBSTR(B.DEPT_ID1,1,2) IN ('TD','TA') THEN 'RD' END PROD_TYPE FROM (
SELECT PRODG,MODULE,COUNT(EQP_G) EQPG_CNT,COUNT(CASE WHEN EQP_ID IS NOT NULL THEN EQP_ID ELSE NULL END ) EQP_CNT FROM ( SELECT C.FAB,C.PRODG,C.CHIPBODY,C.MODULE,C.EQP_G,D.EQP_ID FROM (SELECT A.*,B.EQP_G,B.MODULE FROM ( SELECT * FROM A1MFG.NTO_PRODG_MAINTAIN WHERE FLAG='Y' AND IF_INPUTOVER200_FLAG IS NOT NULL AND FAB IS NOT NULL AND TD_UPDATE_USER='SYS' )A ,( SELECT DISTINCT MODULE,EQP_G FROM ( SELECT MODULE,EQP_G FROM PWEB.EQP_ID_USE_STD WHERE MODULE NOT IN ('FA','INT') AND EQP_G NOT IN ('WR_Metal_cln','WRA_Al film RMV','WRC_Cu Remove','WRM_Ox-SiN/PD_Cln(Before)','WRM_Ox-SiN_Cln(After)','WRO_Ox-SiN Cln(Before)' ,'WRP_P/D cln(After)','WRP_P/D cln(Before)','WS_FOUP Cln','FA_Oxi(After)','FA_Oxi(Before)','FA_Oxi(Cu)') UNION ALL SELECT MODULE,EQP_G FROM PWEB.EQP_ID_USE_STD_A3 WHERE MODULE NOT IN ('FA','INT') AND EQP_G NOT IN ('WR_Metal_cln','WRA_Al film RMV','WRC_Cu Remove','WRM_Ox-SiN/PD_Cln(Before)','WRM_Ox-SiN_Cln(After)','WRO_Ox-SiN Cln(Before)' ,'WRP_P/D cln(After)','WRP_P/D cln(Before)','WS_FOUP Cln','FA_Oxi(After)','FA_Oxi(Before)','FA_Oxi(Cu)') ) )B WHERE 1=1)C LEFT JOIN A1MFG.NTO_MFG_MAINTAIN D ON C.PRODG=D.PRODG AND C.CHIPBODY=D.CHIPBODY AND C.EQP_G=D.EQP_G ORDER BY C.EQP_G ) GROUP BY PRODG,MODULE
)A LEFT JOIN PWEB.PRODUCT_OWNER B ON A.PRODG =B.PRODG1 )C LEFT JOIN ( SELECT PROD_TYPE,MODULE,DEPT_ID FROM A1MFG.TD_RD_RELATED_MODULE WHERE MODULE IS NOT NULL UNION ALL SELECT PROD_TYPE,'Measurement' MODULE,LISTAGG(DEPT_ID, '/') WITHIN GROUP (ORDER BY DEPT_ID) DEPT_ID FROM (SELECT DISTINCT PROD_TYPE,DEPT_ID FROM A1MFG.TD_RD_RELATED_MODULE WHERE MODULE IS NULL) GROUP BY PROD_TYPE )E ON C.PROD_TYPE=E.PROD_TYPE AND C.MODULE=E.MODULE WHERE C.DEPT_ID1 IS NOT NULL AND C.RATIO>0.7 AND NOT EXISTS (SELECT 1 FROM (SELECT * FROM A1MFG.NTO_PRODG_MAIL WHERE TYPE='MFG_TO_MODULE')D WHERE C.PRODG=D.PRODG1 AND E.DEPT_ID=D.DEPT_ID)
